{
  "requirements": [
    {
      "target_id": "t0",
      "policy_source_id": "q14",
      "policy_quote": "Before taking any actions that update the booking database (booking, modifying flights, editing baggage, changing cabin class, or updating passenger information), you must list the action details and obtain explicit user confirmation (yes) to proceed.",
      "requirement": "The assistant must explicitly confirm the cancellation details (reservation ID, flight, date, cabin, and amount) with the user before proceeding."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q14",
      "policy_quote": "The agent must also obtain the reason for cancellation (change of plan, airline cancelled flight, or other reasons).",
      "requirement": "The assistant must obtain and acknowledge the user's reason for cancellation (e.g., 'change of plan') before proceeding with the cancellation."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q14",
      "policy_quote": "If any portion of the flight has already been flown, the agent cannot help and transfer is needed.",
      "requirement": "The assistant must ensure that no portion of the flight (e.g., departure) has already occurred before proceeding with cancellation. Exception: If the flight has already taken off, the assistant must transfer the user to a human agent."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q14",
      "policy_quote": "Otherwise, flight can be cancelled if any of the following is true:\n- The booking was made within the last 24 hrs\n- The flight is cancelled by airline\n- It is a business flight\n- The user has travel insurance and the reason for cancellation is covered by insurance.",
      "requirement": "The assistant must verify that the cancellation complies with at least one of the following conditions: booking within the last 24 hours, flight cancellation by the airline, business cabin class, or travel insurance covering the cancellation reason. Exception: If none apply, the assistant must not proceed with cancellation."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q14",
      "policy_quote": "The API does not check that cancellation rules are met, so the agent must make sure the rules apply before calling the API!",
      "requirement": "The assistant must ensure all cancellation rules (e.g., eligibility, reason, flight status) are met before making the `cancel_reservation` tool call."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q14",
      "policy_quote": "The user must provide their user id.",
      "requirement": "The assistant must ensure the user ID is already confirmed (e.g., via `get_user_details`) before proceeding with the cancellation tool call."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q14",
      "policy_quote": "If the user doesn't know their reservation id, the agent should help locate it using available tools.",
      "requirement": "The assistant must ensure the reservation ID is confirmed (e.g., via `get_reservation_details`) before making the `cancel_reservation` tool call."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q14",
      "policy_quote": "The agent must obtain the reason for cancellation (change of plan, airline cancelled flight, or other reasons).",
      "requirement": "The assistant must ensure the cancellation reason is explicitly documented (e.g., 'change of plan') before making the `cancel_reservation` tool call."
    }
  ]
}
